for (int i = 0; i < N - 1; i++) {          // one pass for each position i
    int minIdx = i;                         // assume a[i] is the smallest
    for (int j = i + 1; j < N; j++) {       // scan the unsorted part after i
        if (a[j] < a[minIdx]) {             // use > for descending order
            minIdx = j;                     // only remember the position
        }
    }
    int temp = a[i];                        // ONE swap per pass
    a[i] = a[minIdx];
    a[minIdx] = temp;
}

