#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int a[N] = {64, 25, 12, 22, 11};
    for (int i = 0; i < N - 1; i++) {
        int minIdx = i;
        for (int j = i + 1; j < N; j++) {
            if (a[j] < a[minIdx]) {
                minIdx = j;
            }
        }
        int temp = a[i];
        a[i] = a[minIdx];
        a[minIdx] = temp;
        cout << "Pass " << i + 1 << ":";
        for (int k = 0; k < N; k++) {
            cout << " " << a[k];
        }
        cout << endl;
    }
    return 0;
}

