#include <iostream>
using namespace std;

int main() {
    const int N = 5;
    int a[N] = {29, 10, 14, 37, 13};
    int comparisons = 0;
    int swaps = 0;
    for (int i = 0; i < N - 1; i++) {
        int minIdx = i;
        for (int j = i + 1; j < N; j++) {
            comparisons++;
            if (a[j] < a[minIdx]) {
                minIdx = j;
            }
        }
        if (minIdx != i) {
            int temp = a[i];
            a[i] = a[minIdx];
            a[minIdx] = temp;
            swaps++;
        }
    }
    cout << "Sorted:";
    for (int k = 0; k < N; k++) {
        cout << " " << a[k];
    }
    cout << endl;
    cout << "Comparisons: " << comparisons << endl;
    cout << "Swaps: " << swaps << endl;
    return 0;
}

